import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
  type JxBadgeTone,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const STATUS_CONFIG: Record<ProjectStatus, { label: string; tone: JxBadgeTone }> = {
  active: { label: 'В норме', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Превышена', tone: 'danger' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Редизайн лендинга', quota: 32, status: 'active' },
  { id: 'p2', name: 'Мобильное приложение', quota: 88, status: 'warning' },
  { id: 'p3', name: 'Миграция на облако', quota: 104, status: 'over' },
  { id: 'p4', name: 'Аналитика продаж', quota: 12, status: 'active' },
  { id: 'p5', name: 'Внутренний портал', quota: 67, status: 'active' },
  { id: 'p6', name: 'Интеграция с CRM', quota: 95, status: 'warning' },
  { id: 'p7', name: 'Служба поддержки', quota: 45, status: 'active' },
  { id: 'p8', name: 'API платформа', quota: 110, status: 'over' },
  { id: 'p9', name: 'Маркетинговый сайт', quota: 58, status: 'active' },
  { id: 'p10', name: 'Биллинг', quota: 91, status: 'warning' },
  { id: 'p11', name: 'Дашборд метрик', quota: 20, status: 'active' },
  { id: 'p12', name: 'Складской учёт', quota: 101, status: 'over' },
];

const ALL_STATUSES: ProjectStatus[] = ['active', 'warning', 'over'];
const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeFilters, setActiveFilters] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((p) => activeFilters.includes(p.status)),
    [activeFilters]
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const removeFilter = (status: ProjectStatus) => {
    setActiveFilters((prev) => prev.filter((s) => s !== status));
    setPage(1);
  };

  const toggleFilter = (status: ProjectStatus) => {
    setActiveFilters((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveFilters(ALL_STATUSES);
    setPage(1);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-lg)',
        padding: 'var(--jx-r-lg)',
        background: 'var(--jx-surface)',
        borderRadius: 'var(--jx-r-lg)',
        border: '1px solid var(--jx-border)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
        maxWidth: 480,
      }}
    >
      <div>
        <div
          style={{
            fontSize: 14,
            fontWeight: 600,
            color: 'var(--jx-text-2)',
            marginBottom: 'var(--jx-r-sm)',
          }}
        >
          Фильтр по статусу
        </div>
        <div style={{ display: 'flex', gap: 'var(--jx-r-sm)', flexWrap: 'wrap' }}>
          {ALL_STATUSES.map((status) => {
            const isActive = activeFilters.includes(status);
            return (
              <JxChip
                key={status}
                active={isActive}
                removable={isActive}
                onRemove={() => removeFilter(status)}
                onClick={() => toggleFilter(status)}
              >
                {STATUS_CONFIG[status].label}
              </JxChip>
            );
          })}
        </div>
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          message="Попробуйте сбросить фильтры, чтобы увидеть все проекты."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-r)',
                  padding: 'var(--jx-r)',
                  background: 'var(--jx-surface-2)',
                  borderRadius: 'var(--jx-r)',
                  border: '1px solid var(--jx-border)',
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-r)' }}>
                  <JxProgressCircle value={Math.min(project.quota, 100)} showValue />
                  <span style={{ fontWeight: 500 }}>{project.name}</span>
                </div>
                <JxBadge tone={STATUS_CONFIG[project.status].tone} dot>
                  {STATUS_CONFIG[project.status].label}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

